<script setup lang="ts">import{onMounted,ref}from'vue';import{ShoppingBag}from'@lucide/vue';import{api,errorMessage}from'../lib/api';import StatusBadge from'../components/StatusBadge.vue';const rows=ref<any[]>([]),loading=ref(true),error=ref('');const next:Record<string,string>={ACCEPTED:'PREPARING',PREPARING:'IN_TRANSIT',READY_FOR_PICKUP:'IN_TRANSIT',IN_TRANSIT:'DELIVERED',DELIVERED:'COMPLETED'};const label=(s:string)=>(next[s]??'').replaceAll('_',' ');async function load(){loading.value=true;try{rows.value=(await api.get('/orders')).data.data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}async function advance(row:any){const status=next[row.status];if(!status)return;try{await api.post(`/orders/${row.id}/status`,{status});await load()}catch(e){error.value=errorMessage(e)}}onMounted(load)</script>
<template><div class="page-heading"><div><p class="eyebrow">FULFILMENT</p><h1>Orders</h1><p>Track accepted B2B requests from preparation through completion.</p></div></div><div v-if="error" class="form-error">{{error}}</div><article class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Buyer</th><th>Seller</th><th>Value</th><th>Updated</th><th>Status</th><th>Next step</th></tr></thead><tbody><tr v-if="loading"><td colspan="7">Loading…</td></tr><tr v-for="row in rows" v-else :key="row.id"><td><RouterLink :to="`/orders/${row.id}`"><strong>{{row.request.listing.title}}</strong></RouterLink></td><td>{{row.buyerOrganization.name}}</td><td>{{row.sellerOrganization.name}}</td><td>{{Number(row.totalAmount).toLocaleString()}} {{row.currency}}</td><td>{{new Date(row.updatedAt).toLocaleDateString()}}</td><td><StatusBadge :status="row.status"/></td><td><button v-if="next[row.status]" class="text-button success" @click="advance(row)">Move to {{label(row.status)}}</button><span v-else>—</span></td></tr></tbody></table></div><div v-if="!loading&&!rows.length" class="empty"><ShoppingBag/><strong>No orders yet</strong></div></article></template>
